INSERT INTO `services` (`id`, `heading`, `slug`, `paragraph`, `main_img`, `small_pag`, `first_heading`, `note`, `content`, `sec_heading`, `sec_imag`, `sec_paragraph`, `third_heading`, `list`, `serviceCat_id`, `created_at`, `updated_at`, `ext_images`) VALUES
(1, 'External Audit', 'external-audit', '<p>An external audit is an independent third-party examination of a company’s financial statements, records, and operations. Its primary purpose is to provide an unbiased opinion about the accuracy and fairness of financial reporting, ensuring compliance with relevant regulations, financial standards, and accounting practices while increasing confidence and value.</p><p>Our auditing process is systematic and dynamic enough to suit your needs. We begin with strategic planning, which involves understanding your business environment and internal controls to conduct a focused audit. Following this, we gather and evaluate evidence, testing financial transactions and analyzing system controls to assess accounting accuracy. Throughout the process, we continuously communicate findings, culminating in a comprehensive report on financial statements, offering valuable insights on internal controls and risk management.</p>', 'uploads/services/1786691584_main_service-about.webp', 'Elevate Your Business with Expert External Audit', 'About External Audit', '<p><strong>By choosing Expert House Chartered Accountants, you are partnering with a firm that combines local expertise with global standards, ensuring your external audit is not just a formality, but a strategic tool for success in Dubai’s dynamic market.</strong></p>', NULL, '<h2><strong>Objectives of External Audit</strong></h2>', 'uploads/services/1786691584_second_service-image2.png', '<p><strong>The primary purpose of an external audit is to provide an objective opinion on whether a company’s financial statements are prepared fairly and accurately, in accordance with applicable accounting standards and regulations.</strong></p><ol><li><strong>Expert team of auditors:</strong>Team Expert CA has highly qualified auditors providing audit services in UAE. We have the best of the professionals in the industry to ensure that you get real value for your audit investment.</li><li><strong>Time bound Audit:</strong>We place strong emphasis on delivering timely and smooth completion of your audit. As a client of Expert CA, you get a dedicated manager who ensures the audit is completed within agreed deadlines.</li><li><strong>Compliance with industry best practices and standards:</strong>Our audit procedures align with International Financial Reporting Standards (IFRS), International Standards on Auditing (ISA), and UAE regulatory frameworks to guarantee complete compliance.</li><li><strong>Affordable Professional Charges:</strong>We always make sure the audit we deliver exceeds the price we charge. Providing top-notch service at the most affordable price has always been our priority.</li></ol>', '<h2><strong>Why Expert House Chartered Accountants</strong></h2>', '[{\"heading\":\"Expert team of auditors:\",\"summary\":\"Team Expert CA has independent, objective and highly-qualified auditors providing audit services in UAE. We have the best of the professionals in the industry to ensure your financial statements are accurate and reliable.\"},{\"heading\":\"Time-bound Audit:\",\"summary\":\"We place strong emphasis on delivering timely and smooth completion of your audit. As a client of Expert CA, we always make sure your audit is delivered on time according to the audit agreement.\"},{\"heading\":\"Compliance with industry best practices and standards:\",\"summary\":\"Our audit procedures align with the latest procedures and standards. Our auditors maintain complete compliance with International Financial Reporting Standards (IFRS), International Standards on Auditing (ISA), and relevant UAE frameworks.\"},{\"heading\":\"Affordable Professional Charges:\",\"summary\":\"We always make sure the audit we deliver exceeds the price we charge. Providing top-notch service at the most affordable price has always been our priority.\"}]', 3, '2026-08-14 01:43:04', '2026-08-26 14:55:24', NULL),
(6, 'Internal Audit', 'internal-audit', '<p>In today\'s fast-paced and complex business world, navigating risks, ensuring compliance, and optimizing performance are not just desirable—they\'re a necessity. While many companies focus on external audits to meet regulatory requirements, the true engine of sustainable growth and operational excellence lies in a robust Internal Audit function.</p><p>&nbsp;</p><p>An effective internal audit is more than just a regulatory box to check—it\'s a powerful tool for strategic growth. At Expert House, our chartered accountants specialize in delivering comprehensive internal audit services that go beyond simple compliance. We help you identify and mitigate risks, enhance operational efficiency, and protect your assets, giving you the clarity and confidence to make sound business decisions.</p>', 'uploads/services/1787571081_main_1756967874702_image-container-2-.webp', 'Know why internal audit is essential for your company', 'About Internal Audit', '<p><strong>We will help you identify potential problems before they escalate, ensuring that your business is not just compliant but also resilient and well-prepared for the future.</strong></p>', NULL, NULL, NULL, NULL, '<h4>Key Benefits of Internal Audit</h4>', '[{\"heading\":\"Risk Mitigation:\",\"summary\":\"We identify and assess potential risks across all areas of your business\\u2014from financial and operational to technological and reputational. Our proactive approach helps you build a more secure and stable foundation for growth.\"},{\"heading\":\"Operational Efficiency:\",\"summary\":\"Our audits go beyond the numbers. We analyze your processes and workflows to pinpoint inefficiencies, redundancies, and areas where you can optimize resources and reduce costs.\"},{\"heading\":\"Enhanced Financial Controls:\",\"summary\":\"We review and strengthen your internal controls to safeguard your assets, prevent fraud, and ensure the integrity of your financial reporting.\"},{\"heading\":\"Compliance Assurance:\",\"summary\":\"We help you navigate the complex landscape of regulations and industry standards, ensuring that your company remains compliant and avoids costly penalties.\"},{\"heading\":\"Strategic Insight:\",\"summary\":\"Our comprehensive reports provide your management team with actionable intelligence. We offer clear recommendations and strategic advice that empower you to make informed decisions and drive your business forward.\"}]', 3, '2026-08-24 11:31:21', '2026-08-24 11:32:50', NULL),
(7, 'Revenue/Sales Audit', 'revenuesales-audit', '<p>At Expert House Chartered Accountants, we believe that understanding your revenue is the key to unlocking sustainable growth. It\'s more than just a number on your financial statement; it\'s a story of your business\'s health, efficiency, and future potential.</p><p>&nbsp;</p><p>Our specialized services in Revenue Audits and Sales Reports are designed to give you a clear, data-driven picture of your business\'s performance.</p>', 'uploads/services/1787573534_main_1756970000161_image-container.webp', 'Unlock Your Business\'s Full Potential: The Power of Revenue Audits & Sales Reports', 'Revenue Audits & Sales Reports', NULL, NULL, '<p>Revenue Audits: Ensuring Accuracy, Mitigating Risk, and Maximizing Profit</p>', NULL, '<p>A revenue audit is a meticulous examination of your company\'s income streams. It\'s an essential process for any business, especially those with complex sales models like e-commerce, to ensure accuracy, compliance, and to uncover hidden opportunities.</p>', '<h4>Why is a Revenue Audit Critical for Your Business?</h4>', '[{\"heading\":\"Financial Accuracy & Integrity:\",\"summary\":\"We verify that your recorded revenue is accurate, ensuring that all transactions are correctly recognized and properly documented. This provides a true and fair view of your financial health.\"},{\"heading\":\"Compliance and Risk Management:\",\"summary\":\"We help you navigate complex accounting standards (such as IFRS 15 or ASC 606) and legal regulations. Our audit procedures are designed to identify and rectify any potential non-compliance, protecting your business from penalties and reputational damage.\"},{\"heading\":\"Leakage and Fraud Detection:\",\"summary\":\"We analyze your revenue cycle to identify any \\\"leakages\\\" \\u2014unbilled services, missed payments, or fraudulent activities\\u2014that could be costing you significant revenue. Our rigorous checks help you seal these gaps.\"},{\"heading\":\"Optimizing Pricing and Strategy:\",\"summary\":\"By analyzing revenue streams, we can provide insights into which products or services are most profitable. This information empowers you to optimize your pricing strategy and focus on your most valuable offerings.\"}]', 3, '2026-08-24 11:33:41', '2026-09-07 12:11:43', NULL),
(8, 'Stock Audit', 'stock-audit', '<p>A stock audit is a physical verification and valuation of a company\'s inventory. Stock audit services are also known as inventory verification services. The objective of the stock audit is to prove and verify the accuracy, existence, and ownership rights and ensure the value of the items in the company’s inventory.</p><p>&nbsp;</p><p>Stock audit needs proper planning, resources, and expertise. Our stock auditors can assist you with the verification of inventory and give more clear and deeper insights into your stock along with a proper reconciliation of existing stock records. Inventory verification ensures the accuracy and correctness of inventory. Expert Chartered Accountants is one of the leading audit firm in UAE to provide all types of audit services. The audit also assesses the condition and value of the inventory, identifying any discrepancies, damage, or obsolescence.</p>', 'uploads/services/1787573815_main_1756986448220_image-container-3-.webp', 'Navigating Tax Audits in the UAE: Your Guide to Compliance', 'About Stock Audit', NULL, NULL, '<h4>Why is a Stock Audit Crucial for Your Business?</h4>', NULL, '<p>A stock audit is not just about counting items; it\'s a vital procedure that provides a clear and accurate picture of a business\'s financial health.</p><p>&nbsp;</p><p>It offers multiple benefits:</p><ul><li><strong>Financial Accuracy and Reporting: </strong>A stock audit ensures that your financial statements, including the balance sheet and profit &amp; loss statement, are accurate and reliable. Since inventory is a major asset, any discrepancies can lead to significant errors in your company\'s valuation.</li><li><strong>Risk Identification and Mitigation: </strong>The audit helps to identify potential risks like pilferage, theft, fraud, or damage. By highlighting these issues, it allows management to take corrective action, strengthen internal controls, and minimize future losses.</li><li><strong>Operational Efficiency: </strong>By identifying discrepancies and slow-moving or obsolete stock, a stock audit helps businesses optimize their inventory management. This leads to better cash flow, reduced carrying costs, and more efficient use of warehouse space.</li><li><strong>Compliance and Credibility: </strong>Many banks and financial institutions require a stock audit for loan sanctions and credit assessment. An independent audit report provides a high level of credibility and transparency to lenders, investors, and other stakeholders, demonstrating a commitment to sound financial practices.</li></ul><p>Our team of stock auditors is well experienced to conduct a stock audit from a small volume stock to a large volume stock. Expert House Chartered Accountants provides the best stock audit services that give more awareness and intuition into your stock along with a proper reconciliation of stock accounts.</p><p>&nbsp;</p><p>Our stock audit services identify the slow-moving stock, deadstock, obsolete stock, and scrap of your organization. Our experts update the physical stock that matches the book stock and helps you to find out discrepancies between book stocks and physical stock. Expert Auditing ensures the proper preservation and handling of the stocks for your business.</p>', NULL, '[]', 3, '2026-08-24 11:34:23', '2026-09-07 12:53:38', NULL),
(9, 'Tax Audit', 'tax-audit', '<p>As a business owner or a professional, navigating the complexities of income tax regulations can be challenging. At Expert House Chartered Accountants, we understand the importance of timely and accurate tax compliance. Our specialized Tax Audit services are designed to help you meet your statutory obligations, minimize risks, and gain a clearer picture of your financial health</p><p>&nbsp;</p><p>A tax audit is an official examination of a company\'s tax records and financial affairs by the Federal Tax Authority (FTA). The purpose of an audit is to verify that a business has correctly calculated and paid its tax liabilities in accordance with UAE tax laws and procedures.</p>', 'uploads/services/1787574165_main_1756991337337_image-container-4-.webp', 'Navigating Tax Audits in the UAE: Your Guide to Compliance', 'About Tax Audit', '<p><strong>With the introduction of Corporate Tax in the UAE, tax audits have become even more critical. Corporate Tax is an official review by the FTA to verify that your business has accurately calculated its taxable income, applied the correct deductions and exemptions, and paid its tax liability in full. For certain entities, such as Qualifying Free Zone Persons or businesses with an annual revenue exceeding AED 50 million, maintaining professionally audited financial statements is a mandatory requirement under the law.&nbsp;</strong></p>', NULL, '<h4>Different types of Tax Audit</h4>', 'uploads/services/1787574165_second_1756991785920_rectangle-4310-1-.png', '<p>The FTA may conduct different types of audits, including:</p><ul><li><strong>Corporate Tax: To ensure compliance with the UAE Corporate Tax Law.</strong></li><li><strong>VAT: To verify the accuracy of VAT returns, including input tax claims and output tax calculations.</strong></li><li><strong>Excise Tax: To review compliance with excise tax regulations.</strong></li></ul>', '<h4>How Expert House Chartered Accountants Can Help You</h4>', '[{\"heading\":\"Proactive Tax Health Checks and Preparation:\",\"summary\":\"We don\'t wait for an audit notice. Our team conducts a detailed review of your books, records, and internal controls to identify potential risks and address them proactively.\"},{\"heading\":\"Expert Representation During the Audit:\",\"summary\":\"If your business is selected for an audit, our experts can act as your authorized tax agents, handling all communication with the FTA.\"},{\"heading\":\"Remediation and Dispute Resolution:\",\"summary\":\"In the event of an unfavorable audit finding, we can assist you with Preparing and submitting voluntary disclosures and Filing reconsideration requests or appeals against a tax assessment or penalty.\"}]', 3, '2026-08-24 11:34:47', '2026-09-07 13:40:42', NULL),
(10, 'Due Diligence', 'due-diligence', '<p>Due diligence is the comprehensive investigation of a business or individual before signing a contract or entering into a major transaction. In the dynamic business environment of the UAE, this process is essential for mitigating risks, identifying opportunities, and making informed decisions.&nbsp; At Expert House Chartered Accountants, we provide a thorough and strategic due diligence service that helps you uncover all the critical details, ensuring that you can proceed with confidence and a clear understanding of the true value and potential liabilities of a deal.</p><p>Properly assessing the value of potential acquisitions and investments through due diligence can be imperative to the success of a transaction. Quality of earnings concerns, operations, market trends, culture issues and other areas all require a closer look to assess risks and determine a company’s true value.</p>', 'uploads/services/1788788677_main_1756995690908_image-container-5-.webp', 'Comprehensive investigation of a business or individual before signing a contract', 'About Due Diligence', '<p><strong>At Expert House Chartered Accountants, we leverage our deep understanding of the UAE\'s legal and economic framework to provide you with actionable insights. We don\'t just present data; we deliver a clear and concise report that highlights key risks and opportunities, enabling you to make a confident and strategic decision.&nbsp;</strong></p>', NULL, '<h4>Our Comprehensive Due Diligence Services</h4>', NULL, '<p>Expert House Chartered Accountants offers a tailored due diligence approach that goes beyond a basic financial review. We provide a holistic assessment to give you a complete picture of the situation. Our services include:</p><h3><strong>Financial Due Diligence</strong></h3><p>This is the core of our service. We conduct an in-depth analysis of a company\'s financial records to assess its historical performance, identify hidden costs, and confirm the quality of its earnings. We scrutinize:</p><ul><li>Balance sheets and income statements.</li><li>Cash flow trends and projections.</li><li>Working capital, assets, and liabilities.</li><li>Tax compliance and potential liabilities under UAE Corporate Tax and VAT laws.</li></ul><h3><strong>Operational &amp; Commercial Due Diligence</strong></h3><p>We look at the \"engine\" of the business. Our team evaluates the operational processes, management efficiency, and market position to determine the company\'s long-term sustainability and growth potential. This includes an analysis of:</p><ul><li>Key business processes and systems.</li><li>Customer and supplier relationships.</li><li>Competitive landscape and market trends.</li><li>The overall operational structure and management capabilities.</li></ul><h3><strong>Legal Due Diligence</strong></h3><p>In partnership with legal professionals, we review a company\'s legal standing to uncover any potential legal risks. This is critical for avoiding future disputes. We examine:</p><ul><li>Corporate documents, licenses, and permits.</li><li>Material contracts and agreements.</li><li>Pending or past litigation and legal disputes.</li><li>Compliance with UAE labour law and other regulatory frameworks.</li></ul><h3><strong>Environmental Due Diligence</strong></h3><p>It provides a critical and independent assessment whether the company complies with the environmental policy or not.</p><h3><strong>People Due Diligence</strong></h3><p>The People Due Diligence involves the study of the old organizational structure and the new one which might be established if the acquisition is a success, and the study of the employment contracts between the company and its employees, costs of terminations if any and the potential benefits.</p>', NULL, '[]', 3, '2026-08-24 11:37:34', '2026-09-07 13:50:02', NULL),
(11, 'Liquidation Report', 'liquidation-report', '<p>Liquidation is the formal process of closing a company, dissolving its legal existence, and settling all its affairs. Whether you\'re a business owner in a Mainland, Free Zone, or Offshore jurisdiction, navigating the liquidation process in the UAE requires strict adherence to legal and regulatory procedures. A company liquidation audit report is required by the authorities before the cancellation of the trade license. A liquidation audit report will list the liabilities and assets of the company.</p><p>At Expert House Chartered Accountants, we provide comprehensive liquidation services to ensure your company closure is handled efficiently, legally, and without unnecessary complications. We act as your appointed liquidator, guiding you through every stage to secure a clean and final exit.</p>', 'uploads/services/1788789272_main_1757052355503_image-container-6-.webp', 'Formal process to dissolve a company’s existence', 'About Liquidation Report', NULL, NULL, '<h4>Why You Need a us for Liquidation</h4>', NULL, '<p>Attempting to liquidate a company without professional help can be a complex, time-consuming, and risky process. A licensed chartered accountant acts as your trusted partner, ensuring:</p><ul><li><strong>Legal Compliance: </strong>We stay up-to-date with all local laws and regulations, ensuring your liquidation is fully compliant from start to finish, preventing future liabilities and penalties.</li><li><strong>Efficiency: </strong>We streamline the process, managing all communication with government authorities and creditors, and ensuring a smooth, timely closure</li><li><strong>Expert Reporting: </strong>Our expertise in financial reporting guarantees that all liquidation reports and statements of affairs are accurate and meet regulatory standards.</li><li><strong>Asset Protection: </strong>We ensure the proper valuation and distribution of assets, protecting the interests of all stakeholders, including shareholders and creditors.</li></ul><p>At Expert House, we believe in a transparent, hassle-free approach. Contact us today to discuss your company liquidation needs and ensure a confident, legally sound business closure.</p>', NULL, '[]', 3, '2026-08-24 11:38:08', '2026-09-07 13:55:42', NULL),
(12, 'Outsourced Accounting Services', 'outsourced-accounting-services', '<p>Expert CA offers professional accounting, bookkeeping, and VAT services tailored to businesses of all sizes. With a highly trained team of Chartered Accountants &amp; CPAs in Dubai and India, we ensure accurate, compliant, and cost-effective financial management. Our experts handle everything from advanced bookkeeping and auditing to specialized software support like QuickBooks, Zoho, Odoo, Xero, and Tally ERP. With over 10 years of experience in the UAE, we help businesses save time, reduce costs, and focus on growth while we manage their accounts with precision and professionalism.</p>', 'uploads/services/1788789510_main_1758699478397_image-container-14-.webp', 'Simplify your business with Expert CA’s reliable outsourced accounting services.', 'About Outsourced Accounting Services', NULL, '<h2>First Content&nbsp;</h2><p><strong>Lorem Ipsum</strong> is simply dummy text of the printing and typesetting industry. Lorem Ipsum has been the industry\'s standard dummy text ever since 1966, when designers at Letraset and James Mosley, the librarian at St Bride Printing Library in London, took a 1914 Cicero translation and scrambled it to make dummy text for Letraset\'s Body Type sheets. It has survived not only many decades, but also the leap into electronic typesetting, remaining essentially unchanged. It was popularised thanks to these sheets and more recently with desktop publishing software like Aldus PageMaker and Microsoft Word including versions of Lorem Ipsum.</p><figure class=\"image\"><img style=\"aspect-ratio:2560/1707;\" src=\"http://127.0.0.1:8000/uploads/ckeditor/1790335697_6ab65ad1eee5f.jpg\" width=\"2560\" height=\"1707\"></figure>', '<h4>Outsourced Accounting Services</h4>', NULL, '<p>The <strong>Outsourcing Accounting Team of Expert CA</strong> constantly <strong>invests in the human talent, technology and training to meet the global standard</strong> of accountings. Best professional Chartered Accountants &amp; CPAs are working at Expert House in the big setup of Dubai &amp; India. Here we maintain a high level of ethics and professionalism to maintain the accounts of our clients. Our <strong>thorough understanding of the local market</strong> across the industry helps us to make the work faster and accurate. Our accumulated client base represents diverse industries F&amp;B, Manufacturing, Education, Pharmaceutical, Retail, Construction etc.</p><p>When you start a business, in the beginning days you need someone experienced to advise you how to be compliant in terms of Accounting, Book Keeping, Auditing and VAT. This is the time when you’ll need more advanced bookkeeping, accounting and management or managerial accounting to help you make data-driven decisions. Experts have developed a clear understanding how to hand hold the Business Owner to have control over accounting &amp; finance.</p><p><strong>Companies with a light volume of transactions</strong> that are recorded in non-accounting software like Microsoft Excel can <strong>outsource their work</strong> to Expert Accounting. We have our existing licenses from several accounting software that will help to maintain our client’s accounts in a professional way, you can get your accounting done professionally without any additional cost of buying an accounting software.</p><p>Accounting &amp; Bookkeeping for Small Business Expert House has a wonderful cost-effective arrangement that is perfectly working for many business owners. Partnering with Expert brings peace of mind, confidence between partners to concentrate more into the core business.</p><p>In the UAE there is a law that makes maintaining accounting mandatory. <strong>UAE Federal law no-2 of 2015, Article No-26 has made Accounting Mandatory</strong> and you need to keep your book of accounts for 5 years from the end of the financial year of the company.</p><p>Our team can also <strong>take care of a very complex accounting system by sending our certified and experienced accountants</strong> from our Dubai office to the client’s place. They are professionally trained to work in almost all popular accounting software like QuickBooks, ZOHO, ODOO, XERO, Tally ERP. Understanding the effectiveness of outsourcing, Companies registered in DIFC, Dubai Mainland, DMCC have outsourced their Accounting &amp; Book Keeping work to Expert CA.</p><p>The basic benefits of Outsourcing Accounting Services are in the budget package you get services of Accountant, Accounts Manager, VAT Experts who are professionally trained and have more than 10 years of experience in UAE.</p>', NULL, '\"[]\"', 4, '2026-08-24 11:38:56', '2026-09-25 05:58:24', '\"[\\\"uploads\\\\\\/services\\\\\\/1790228429_external_6ab4b7cd084b6.PNG\\\",\\\"uploads\\\\\\/services\\\\\\/1790229456_external_6ab4bbd010ff7.PNG\\\"]\"'),
(14, 'Corporate Tax', 'corporate-tax', '<p>The United Arab Emirates has officially introduced a federal Corporate Tax (CT) on business profits, effective for financial years starting on or after June 1, 2023. This landmark change is part of the UAE\'s strategy to diversify its economy and align with global tax transparency standards. While the new law applies to most businesses, a tiered system and a number of exemptions aim to support small businesses and maintain the country\'s competitive business environment.</p>', 'uploads/services/1788845702_main_1757400723064_image-container-8-.webp', 'Navigating UAE’s New Tax Landscape with Confidence', 'About Corporate Tax', NULL, NULL, '<h4>Who is Subject to Corporate Tax?</h4>', 'uploads/services/1788845702_second_1757401402892_rectangle-4310-2-.png', '<ul><li>All businesses and commercial activities operating under a license in the UAE are subject to the tax.</li><li>Individuals conducting business activities will also be subject to CT if their annual turnover exceeds a specified threshold.</li><li>Foreign entities will be taxed on income derived from a Permanent Establishment in the UAE.</li></ul>', '<h4>Exemptions &amp; Special Provisions</h4>', '[{\"heading\":\"The UAE Corporate Tax Law provides several exemptions to avoid double taxation and support specific sectors. These include:\",\"summary\":\"Government entities and entities controlled by the government.\\r\\nExtractive businesses (e.g., oil and gas) that are subject to Emirate-level taxation.\\r\\nQualifying Public Benefit Entities and Qualifying Investment Funds.\\r\\nDividends and capital gains from qualifying shareholdings.\"}]', 5, '2026-08-24 11:40:33', '2026-09-08 05:35:02', NULL),
(15, 'Value Added Tax', 'value-added-tax', '<p>VAT is a consumption-based tax levied on the supply of most goods and services in the UAE. Introduced on January 1, 2018, the standard VAT rate is 5%, making it one of the lowest globally and ensuring minimal impact on consumers. Certain goods and services, such as basic food items, healthcare, education, and exports, may be exempt or subject to a zero-rate.</p><p>For businesses, compliance involves registering with the Federal Tax Authority (FTA), maintaining accurate records, and filing periodic returns, making VAT an important part of financial planning and day-to-day operations.</p>', 'uploads/services/1788846324_main_1757403763390_image-container-9-.webp', 'Streamlined VAT Solutions for Smarter Business', 'About VAT', NULL, NULL, '<h4>Our VAT Services</h4>', NULL, '<p>At Expert House, we offer a full suite of services to ensure your business is compliant and tax-efficient:</p><ul><li><strong>VAT Registration: </strong>We\'ll determine if your business meets the mandatory or voluntary registration thresholds and handle the entire registration process with the Federal Tax Authority (FTA).</li><li><strong>VAT Return Filing: </strong>We prepare and file your periodic VAT returns accurately and on time, ensuring all transactions are correctly accounted for.</li><li><strong>VAT Planning and Advisory: </strong>Our experts provide strategic advice to help your business optimize its VAT position and understand its obligations regarding input tax recovery and cross-border transactions.</li><li><strong>VAT Compliance and Audits: </strong>We ensure your records are maintained in accordance with FTA regulations and provide representation and support during any FTA audits or inquiries.</li></ul>', '<h4>Why Timely VAT</h4>', '[]', 5, '2026-08-24 11:41:08', '2026-09-08 05:45:24', NULL),
(16, 'Economic Substance Regulations', 'economic-substance-regulations', '<p>Introduced in the UAE in April 2019, the Economic Substance Regulations were designed to align with global standards and combat harmful tax practices. These regulations require certain UAE-based companies carrying out “relevant activities” — such as banking, insurance, shipping, intellectual property, or holding company activities — to demonstrate that they have genuine economic operations in the country.</p><p>The purpose is to ensure that companies are not merely shell entities established to shift profits but instead contribute real value to the UAE economy.</p>', 'uploads/services/1788846929_main_1757408547420_image-container-10-.webp', 'Compliance That Strengthens Your Economic Footprint', 'About ESR', NULL, NULL, '<h4>Who Must Comply with ESR?</h4>', NULL, '<p>The regulations apply to all UAE-licensed businesses, including those in free zones, that conduct one or more of the nine specific Relevant Activities. If a company carries out one of these activities, it must file an annual ESR Notification and, if it earns income from that activity, an ESR Report.</p>', '<h4>Annual Notification &amp; Economic Substance Report.</h4>', '[]', 5, '2026-08-24 11:41:38', '2026-09-08 05:55:29', NULL),
(17, 'Ultimate Beneficial Ownership', 'ultimate-beneficial-ownership', '<p>In today’s evolving business environment, transparency and compliance are more important than ever. The UAE has introduced Ultimate Beneficial Ownership (UBO) regulations to ensure accountability, prevent money laundering, and enhance corporate governance.</p><p>A UBO (Ultimate Beneficial Owner) is the individual who ultimately owns or controls a company, directly or indirectly, regardless of whether their name appears in official records. Identifying the UBO helps authorities and businesses maintain transparency and integrity in financial transactions.</p>', 'uploads/services/1788847738_main_1757415791123_image-container-12-.webp', 'Strengthening Corporate Governance and Accountability', 'About UBO', NULL, NULL, '<h4>Why UBO Matters in the UAE</h4>', NULL, '<p>The UAE has mandated companies to maintain and submit UBO registers in compliance with Cabinet Resolution No. 58 of 2020 on the Regulation of Procedures Related to Real Beneficiaries. Failure to comply with UBO regulations can result in penalties, reputational risks, and operational challenges. <strong>By ensuring UBO compliance, businesses can:</strong></p><ul><li>Build investor and stakeholder confidence</li><li>Reduce regulatory and legal risks</li><li>Support the UAE’s commitment to international financial standards</li></ul>', '<p>Third level heading</p>', '[]', 5, '2026-08-24 11:42:13', '2026-09-08 06:08:58', NULL),
(18, 'In-Country Value', 'in-country-value', '<p>The In-Country Value (ICV) program is a key initiative launched by the UAE government to boost the country’s economic growth and promote local content. It encourages companies to contribute to the UAE economy by prioritizing local suppliers, creating job opportunities for Emiratis, and supporting the development of the national industrial sector.</p>', 'uploads/services/1788848502_main_1757417603806_image-container-13-.webp', 'Empowering UAE’s Economy with ICV Compliance', 'About ICV Certification', NULL, NULL, '<h4>What is ICV?</h4>', NULL, '<p>The ICV program, introduced by ADNOC and later adopted by several government entities, measures how much a company contributes to the UAE economy. Companies that hold an ICV certificate gain a competitive advantage when bidding for government and semi-government contracts. <strong>Your ICV score is based on several factors, including:</strong></p><ul><li>Goods and services sourced locally</li><li>Investment in the UAE</li><li>Emiratization and employment of UAE nationals</li><li>Exports outside the UAE</li><li>Contribution to GDP through local spending</li></ul>', '<h4>Why ICV Certification Matters?</h4>', '[]', 5, '2026-08-24 11:43:59', '2026-09-08 06:21:42', NULL),
(19, 'Tax Residency Certificate', 'tax-residency-certificate', '<p>The Tax Residency Certificate (TRC), also known as a Tax Domicile Certificate, is an official document issued by the UAE Ministry of Finance. It allows individuals and companies to benefit from the UAE’s extensive Double Taxation Avoidance Agreements (DTAA) with more than 130 countries worldwide.</p>', 'uploads/services/1788848845_main_1757419681342_image-container-14-.webp', 'Your Gateway to Double Taxation Relief', 'Tax Residency Certificate (TRC) in the UAE', '<p><strong>We have been in the industry for over a decade now. Dealing with clients from multiple businesses and backgrounds has given us extensive experience in accounting, auditing and taxation around the world. We can help you in acquiring a Tax Residency Certification based on requirements of your business. We fulfill any TRC related services.</strong></p>', NULL, '<h3><strong>Double Taxation Avoidance Agreement</strong></h3>', NULL, '<p>The Double Tax Avoidance Agreement (DTAA) is a tax treaty signed between two or more countries to help taxpayers avoid paying double taxes on the same income. A DTAA becomes applicable in cases where an individual is a resident of one nation, but earns income in another. All the major countries in the world has entered into DTAA with their economic counterparts to foster international trade. UAE also has entered into DTAA with around 140 countries thus broadening and liberalizing its trade route.</p>', '<h4>What is a TRC?</h4>', '[]', 5, '2026-08-24 11:44:39', '2026-09-08 06:27:25', NULL),
(20, 'AML/CFT Compliance', 'amlcft-compliance', '<p>UAE’s strong commitment to adopt the finest international business practices has no limits. In April, 2020 the Financial Action Task Force (FATF) issued a Mutual Evaluation Report (MER) on the UAE’s compliance level with the FATF 40 recommendations and the level of effectiveness of the existing compliance system. The evaluation also aimed in identifying the threats, vulnerabilities and emerging risks in the UAE’s financial sector. Pursuant to this Central Bank of UAE(CBUAE) established a dedicated wing to handle all Anti-Money Laundering and Combatting the Financing of Terrorism issues.</p>', 'uploads/services/1788849148_main_1757413946155_image-container.webp', 'Ensuring Transparency and Security in Financial Practices', 'About AML/CFT Compliance Services', NULL, NULL, '<h4><strong>Scope</strong></h4>', NULL, '<ul><li><strong>Money Laundering: </strong>In simple terms, the act of concealing the identity of the original source of illegal funds and then making it appear as derived from a legitimate source.</li><li><strong>Financing Terrorism: </strong>The act of funding or financing any terrorist organisations/activities.</li></ul>', '<h4>Applicability of the AML/CFT Framework?</h4>', '[]', 5, '2026-08-24 11:45:06', '2026-09-08 06:44:20', NULL),
(21, 'Bank Account Opening', 'bank-account-opening', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[]', 6, '2026-08-24 11:48:55', '2026-08-26 14:53:47', NULL),
(22, 'Business Consulting', 'business-consulting', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[]', 6, '2026-08-24 11:49:09', '2026-08-26 14:53:21', NULL),
(23, 'Business Valuation', 'business-valuation', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[]', 6, '2026-08-24 11:49:24', '2026-08-26 14:52:52', NULL),
(24, 'CFO Services', 'cfo-services', '<p>CFO services unify the definition of the functional strategy for the finance department. CFO transforms the finance function. CFO services help businesses to cut costs and increase revenues and allows them to control the financial functions of the business. It helps businesses to make better decisions based on reasonable and timely financial advice</p><p>Expert House CFO Services offer a strategy to cover all the financial functions of the organization. We focus on the solutions and address the financial challenges faced by the companies. We are providing high-quality CFO services by managing the core finance activities more efficiently.</p>', 'uploads/services/1788845264_main_1758792872488_image-container-15- (1).webp', 'Expert financial guidance, planning, and insights with our professional CFO services.', 'About CFO Services', NULL, NULL, '<h4>Role of a CFO</h4>', NULL, '<p><strong>CFOs are top level executives in the company hierarchy</strong> who provide core financial oversight, oversee tax procedures and compliance and ensure operational optimization of your finance division. These elite financial controllers <strong>provide some much-needed financial advisory and strategic planning</strong> at the highest level.</p><p>Our CFO services gives businesses in all industry sectors access to this crucial skillset by employing its immensely skilled consultants to oversee their operational optimization. By partnering with us, you get all the necessary analysis, strategic planning, and system integrity without the need to have a top-level employee for the same.</p><p><strong>CFO’s job consists of major roles such as:</strong></p><p>CFO plays a vital role in the growth of a business by analyzing and connecting the financial reports with the operational reports in order to manage the functions of a company in a better way.&nbsp;</p><ul><li>Preparing accurate financial reports</li><li>Preparing annual budgets</li><li>Balancing the internal controls</li><li>Cash flow management and forecasting</li><li>Review of contracts with suppliers and customers</li><li>Tax preparations</li><li>Cost analysis and expense control</li><li>Risk management and business advisory to the CEO</li><li>Cash and capital management</li><li>Expanding the influence of finance function</li></ul>', '<h4>Why go for CFO Services?</h4>', '[]', 4, '2026-09-08 05:27:44', '2026-09-08 05:27:44', NULL);

